// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amount, bytes calldata data) public {
        vm.assume(caller != address(0));
        vm.assume(amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok = true;
        try c.sendMoney(address(0), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(caller, c.owner());
        } else {
            assertTrue(true);
        }
    }
}
